def main():
    raw = (ROOT/'raw/Dhika.txt').read_bytes()
    lines = raw.decode().split('\n')
    headings = [(int(m[1]),i+1) for i,s in enumerate(lines) if (m:=re.fullmatch(r'EPISODE (\d+)',s))]
    by_ep = {e:(a,headings[i+1][1]-1 if i+1<len(headings) else len(lines)) for i,(e,a) in enumerate(headings)}
    records = []
    for e,a,b,track,frame,title,reading in SECTIONS:
        ea,eb=by_ep[e]
        assert ea<=a<=b<=eb, (e,a,b,ea,eb)
        records.append(dict(id=f'REVIEW-E{e:02}-{a}',episode=e,source=[a,b],track=track,frame=frame,title=title,reading=reading,review='SOURCE_LINKED_SECTION_FIRST_PASS',source_sha256=hashlib.sha256('\n'.join(lines[a-1:b]).encode()).hexdigest(),atomic_complete=False))
    episodes=[]
    for e in range(1,69):
        a,b=by_ep[e]
        hits=[n for n in range(a,b+1) if re.search(r'\b(?:Bantu|Bobby|twins?)\b',lines[n-1],re.I)]
        episodes.append(dict(episode=e,source=[a,b],line_count=b-a+1,explicit_name_lines=hits,section_ids=[r['id'] for r in records if r['episode']==e],existing_event_ledger=e<=13,semantic_complete=False,review_status='FIRST_PASS_SECTIONS' if any(r['episode']==e for r in records) else 'EXISTING_FIRST_PASS' if e<=10 else 'NO_NAMED_REFERENCE_PRONOUN_REVIEW_PENDING'))
    output=dict(schema='twins_e01_e68_navigation_review_v1',source='raw/Dhika.txt',source_git_blob='590b4dce02db105b1ff150a118d309fcef7778f2',source_sha256=hashlib.sha256(raw).hexdigest(),scope=[1,68],atomic_complete=False,review_date='2026-10-15',rules=['Every episode has a complete source range, including episodes without name matches.','Authored sections are a first-pass navigation map, not independent exhaustive atomic certification.','Shared-scene context is not pair-specific action evidence.','Memory, report, hypothesis, comparison and remote communication are separate from current in-person meetings.','No source prose is rewritten or duplicated in this dataset.'],episodes=episodes,sections=records,ambiguities=[dict(id='E23-L4229-ACTOR',episode=23,line=4229,issue='Conflicting actor name in the shared sequence; original text retained; do not silently resolve.')])
    path=ROOT/'data/twins_e01_e68_navigation_review_v1.json'
    path.write_text(json.dumps(output,indent=2,ensure_ascii=False)+'\n')
    print(f'{len(episodes)} source ranges; {len(records)} section annotations; atomic completeness remains false')


if __name__=='__main__':
    main()
